//! The harness of lean-runtime's micro-benchmarks (CONTRIBUTING.md, "Performance"). Each binary in
//! `src/bin/` (generated by `scripts/gen_benches.py`) times one public function of
//! `lean_runtime::semantics`; its native twin of the same name in `benches/native/` makes the same
//! calls through Lean's API, with the same operands, and prints the same checksum.
//!
//! A binary takes one argument, the number of calls N. It prints the checksum of the results on
//! stdout line 1 and `kernel_ns <ns>` on line 2: monotonic time read just before the loop of N
//! calls and just after it, the input built before and the result consumed after, both through
//! `black_box`. The timing driver (pinning, alternation, medians) is separate.

#![forbid(unsafe_code)]

use std::hint::black_box;
use std::time::Instant;

/// The LCG both sides draw their operands from: `x' = x * A + C` modulo 2^64.
#[inline(always)]
pub fn step(x: u64) -> u64 {
    x.wrapping_mul(6364136223846793005)
        .wrapping_add(1442695040888963407)
}

/// The LCG's first state.
pub const SEED: u64 = 0x9E37_79B9_7F4A_7C15;

/// The input of the string benchmarks: 64 copies of "a€😀é0123" (characters of 1 to 4 bytes),
/// as `Bench.mixed` in `benches/native/Bench/Harness.lean`.
pub fn mixed() -> String {
    "a€😀é0123".repeat(64)
}

/// Runs one benchmark: N from the single argument, the input built before the first clock read,
/// the kernel's result consumed after the second; prints the result and `kernel_ns <ns>`.
pub fn run<I>(build: fn() -> I, kernel: fn(&I, u64) -> u64) {
    let args: Vec<String> = std::env::args().collect();
    let n = match args.as_slice() {
        [_, n] => n.parse::<u64>().ok(),
        _ => None,
    };
    let Some(n) = n else {
        eprintln!("usage: {} N", args[0]);
        std::process::exit(2);
    };
    let input = black_box(build());
    let n = black_box(n);
    let t0 = Instant::now();
    let out = black_box(kernel(&input, n));
    let ns = t0.elapsed().as_nanos();
    println!("{out}");
    println!("kernel_ns {ns}");
}
